generated_aql:
FOR b IN Businesses
    FILTER b.rating < 1.5
    RETURN { city: b.city }

LET tipsByMonth = (
    FOR t IN Tips
        LET month = t.month, year = t.year
        RETURN {month: month, count: LENGTH(
            FOR u IN Users
                FILTER u.name == (
                    FOR tIn 1..1 OUTBOUND t WritesTip
                        FILTER t._id == t._id
                        RETURN u.name
                )
            )
        }
)

RETURN MAP(
    function(doc) { return {month: doc.month, count: doc.count} },
    UNNEST(
        FOR tip IN tipsByMonth
            GROUP BY tip.month
            SORT BY tip.month
            RETURN tip
    )
)

LET ratings = (
    FOR u IN Users
        FOR r IN 1..1 OUTBOUND u WritesReview
            RETURN r.rating
)

FILTER AVERAGE(ratings) < 3

RETURN {
    user_id: u.user_id,
    name: u.name
}

FOR u IN 1..1 OUTBOUND uid WritesTip
    FILTER u.city == "Dallas"
    RETURN DISTINCT {
        user_id: u.user_id,
        name: u.name
    }
